package hu.bankmonitor.testsupport;

import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.context.annotation.Import;
import org.springframework.test.web.servlet.client.RestTestClient;

/**
 * Base for tests that need the whole application running on a real port.
 *
 * <p>The configuration lives here rather than being repeated on each subclass for a
 * reason beyond tidiness: Spring caches one application context per distinct
 * configuration, so two classes differing by a single annotation pay two boots. Holding
 * the annotations in one place makes the shared context structural rather than a
 * coincidence the next edit could break.
 *
 * <p>{@code RANDOM_PORT} rather than MockMvc, because the claims these tests make are
 * about the servlet container itself — that a request reaches a listening socket, and
 * what kind of thread Tomcat serves it on. MockMvc would bypass it and prove neither.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Import(ThreadProbeController.class)
public abstract class BootedApplicationTest {

	@LocalServerPort
	private int port;

	/**
	 * A client bound to the running server. {@code TestRestTemplate} is gone in Spring
	 * Boot 4; {@code RestTestClient} is its Spring Framework 7 replacement.
	 */
	protected RestTestClient client() {
		return RestTestClient.bindToServer().baseUrl("http://localhost:" + port).build();
	}
}
package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.testsupport.BootedApplicationTest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * The Accounts, the reads and the cleanup the two reservation tests share.
 *
 * <p><b>Nothing here is transactional, and that is the point.</b> A {@code @Transactional}
 * test method makes every write it performs invisible to any other connection and rolls the
 * lot back at the end — which would leave
 * {@link ConcurrentReservationsHoldTheBalanceTest}'s second thread unable to see the first
 * thread's reservation, and every assertion in
 * {@link ReservedFundsReachTheTableTest} agreeing with a transaction that never committed.
 * Both classes need real commits, so the price is paying for the cleanup by hand.
 *
 * <p>The tables are emptied before each method as well as after: one in-memory H2 database is
 * shared by every test in the suite, whichever application context booted it, and the
 * assertions below count rows rather than looking only at their own.
 *
 * <p>Rows go in and come back out in SQL rather than through the entities, so what is
 * asserted is what reached the database — a round trip through the mapping under test would
 * agree with itself whatever it wrote.
 */
abstract class ReservationScenario extends BootedApplicationTest {

	static final Instant REQUESTED_AT = Instant.parse("2026-09-05T10:15:30Z");

	@Autowired
	FundsReservation reservation;

	@Autowired
	JdbcTemplate database;

	/** Ledger first, then Transfers, then Accounts: each table points at the one below it. */
	@BeforeEach
	@AfterEach
	void emptyTheLedgerTransferAndAccountTables() {
		database.update("DELETE FROM check_ledger");
		database.update("DELETE FROM transfers");
		database.update("DELETE FROM accounts");
	}

	/**
	 * With an explicit identifier, which the identity column accepts because it is declared
	 * {@code generated by default}. The lock order is ascending by ID, so a test about two
	 * Accounts needs to be able to say which of them is the lower one.
	 */
	void openAccount(long id, long balanceMinorUnits, Currency currency) {
		database.update("""
				INSERT INTO accounts (id, balance_minor_units, balance_currency,
				                      reserved_amount_minor_units, reserved_amount_currency)
				VALUES (?, ?, ?, 0, ?)
				""", id, balanceMinorUnits, currency.name(), currency.name());
	}

	/**
	 * Reads as the sentence a Transfer is — an amount, out of one Account, into another —
	 * which is deliberately not the order {@link ReservationRequest} declares its components
	 * in. Three adjacent {@code long}s are swappable in silence either way; naming the two
	 * Accounts {@code from} and {@code to} is what makes a swapped call read wrong.
	 */
	static ReservationRequest transferOf(long amountMinorUnits, long fromAccountId, long toAccountId) {
		return new ReservationRequest(fromAccountId, toAccountId, amountMinorUnits, REQUESTED_AT);
	}

	long balanceOf(long accountId) {
		return minorUnitsOf("balance_minor_units", accountId);
	}

	long reservedAmountOf(long accountId) {
		return minorUnitsOf("reserved_amount_minor_units", accountId);
	}

	/** What an overdraft check tests against, read back from the two columns it is derived from. */
	long availableBalanceOf(long accountId) {
		return balanceOf(accountId) - reservedAmountOf(accountId);
	}

	List<Map<String, Object>> transferRows() {
		return database.queryForList("SELECT * FROM transfers ORDER BY id");
	}

	List<Map<String, Object>> checkLedgerRows() {
		return database.queryForList("SELECT * FROM check_ledger ORDER BY id");
	}

	private long minorUnitsOf(String column, long accountId) {
		Long minorUnits = database.queryForObject(
				"SELECT " + column + " FROM accounts WHERE id = ?", Long.class, accountId);
		return minorUnits == null ? 0L : minorUnits;
	}
}
package hu.bankmonitor.testsupport;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.payments.common.Money;
import hu.bankmonitor.payments.transfers.TransferStatus;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.Instant;
import java.time.ZoneOffset;

/**
 * Transfer and Account rows written straight to the tables, for the tests that read
 * Transfers back.
 *
 * <p>Why SQL rather than the application's own path: a Transfer the application can produce
 * is {@code PENDING} and nothing else, because design decision 11 leaves each transition to
 * the ticket that has a caller for it. A test of a listing that reports four statuses cannot
 * be written against a path that reaches one, so the rows are placed rather than made. The
 * same reasoning is recorded in {@code AccountListingTest} for the Available Balance.
 *
 * <p>Static rather than an injected fixture so that a test's {@code @AfterEach} cannot depend
 * on a {@code @BeforeEach} having run first to build it — which is the very ordering trap
 * {@link #startFromTwoAccountsAndNoTransfers} exists to avoid.
 */
public final class TransferRows {

	/** The two Accounts every Transfer written here moves money between. */
	public static final long SOURCE_ACCOUNT = 1L;

	public static final long DESTINATION_ACCOUNT = 2L;

	private TransferRows() {
	}

	/**
	 * Emptied and reopened in one method rather than two: JUnit promises no order between two
	 * {@code @BeforeEach} methods, and opening the Accounts before the delete would leave
	 * every insert that follows without the rows its foreign keys point at.
	 */
	public static void startFromTwoAccountsAndNoTransfers(JdbcTemplate jdbc) {
		empty(jdbc);
		openAccount(jdbc, SOURCE_ACCOUNT, Currency.EUR);
		openAccount(jdbc, DESTINATION_ACCOUNT, Currency.EUR);
	}

	/** Transfers first, then Accounts: each Transfer row points at the two below it. */
	public static void empty(JdbcTemplate jdbc) {
		jdbc.update("DELETE FROM transfers");
		jdbc.update("DELETE FROM accounts");
	}

	public static void openAccount(JdbcTemplate jdbc, long id, Currency currency) {
		jdbc.update("""
				INSERT INTO accounts (id, balance_minor_units, balance_currency,
				                      reserved_amount_minor_units, reserved_amount_currency)
				VALUES (?, 1000000, ?, 0, ?)
				""", id, currency.name(), currency.name());
	}

	/**
	 * One Transfer with an explicit identifier, which the identity column accepts because it
	 * is declared {@code generated by default}. The identifier has to be given rather than
	 * generated: one endpoint is addressed by it and the listing's order is asserted against
	 * it, and neither can be written against whichever value the sequence had reached.
	 */
	public static void insertTransfer(JdbcTemplate jdbc, long id, TransferStatus status, Instant createdAt,
			Money debitedAmount, Money creditedAmount) {
		jdbc.update("""
				INSERT INTO transfers (id, source_account_id, destination_account_id,
				                       debited_amount_minor_units, debited_amount_currency,
				                       credited_amount_minor_units, credited_amount_currency,
				                       status, created_at)
				VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
				""", id, SOURCE_ACCOUNT, DESTINATION_ACCOUNT,
				debitedAmount.minorUnits(), debitedAmount.currency().name(),
				creditedAmount.minorUnits(), creditedAmount.currency().name(),
				status.name(), createdAt.atOffset(ZoneOffset.UTC));
	}
}

